`timescale 1ns / 1ps
// Repro, bucket A (period): with constant duty, rising edges of pwm must be
// exactly PERIOD clock cycles apart.
module tb_pwm_period;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd3;
    wire pwm;
    reg [8*64-1:0] nonce;
    integer passed;
    integer failed;
    integer cyc;
    integer last_rise;
    integer rises;
    reg prev;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    initial begin
        passed = 0;
        failed = 0;
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        rst = 1'b1;
        duty = 4'd3;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        prev = 1'b0;
        last_rise = -1;
        rises = 0;
        for (cyc = 1; cyc <= 6 * PERIOD; cyc = cyc + 1) begin
            @(negedge clk);
            if (pwm === 1'b1 && prev === 1'b0) begin
                if (last_rise >= 0) begin
                    if (cyc - last_rise == PERIOD) begin
                        passed = passed + 1;
                    end else begin
                        failed = failed + 1;
                        $display("CHECK period.rise_spacing FAILED: rising edges %0d cycles apart, expected %0d",
                                 cyc - last_rise, PERIOD);
                    end
                end
                last_rise = cyc;
                rises = rises + 1;
            end
            prev = pwm;
        end
        if (rises >= 4) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK period.edges_seen FAILED: only %0d rising edges in %0d cycles", rises, 6 * PERIOD);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
