`timescale 1ns / 1ps
// Repro, bucket B (pulse width): with constant duty d (0 < d < PERIOD), each
// high run of pwm must last exactly d clock cycles.
module tb_pwm_pulse_width;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd0;
    wire pwm;
    reg [8*64-1:0] nonce;
    integer passed;
    integer failed;
    integer n;
    integer w;
    integer k;
    reg prev;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task run_case;
        input [3:0] d;
        begin
            rst = 1'b1;
            duty = d;
            repeat (3) @(negedge clk);
            rst = 1'b0;
            n = 0;
            w = 0;
            prev = 1'b0;
            for (k = 0; k < 8 * PERIOD && n < 4; k = k + 1) begin
                @(negedge clk);
                if (pwm === 1'b1) begin
                    w = w + 1;
                end else begin
                    if (prev === 1'b1) begin
                        if (w == d) begin
                            passed = passed + 1;
                        end else begin
                            failed = failed + 1;
                            $display("CHECK pulse.width FAILED: duty %0d gave a high run of %0d cycles", d, w);
                        end
                        n = n + 1;
                    end
                    w = 0;
                end
                prev = pwm;
            end
            if (n < 4) begin
                failed = failed + 1;
                $display("CHECK pulse.pulses_seen FAILED: duty %0d gave only %0d complete pulses", d, n);
            end
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        run_case(4'd3);
        run_case(4'd5);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
