// Repro, bucket C (duty update): duty is sampled once, at the first clock of a
// period; a change in the middle of a period must not affect that period.
module tb_pwm_duty_update;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd0;
    wire pwm;
    reg [8*64-1:0] nonce;
    integer passed;
    integer failed;
    integer k;
    integer w;
    integer lows;
    reg done;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    initial begin
        passed = 0;
        failed = 0;
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;

        // Scenario 1: raise duty just after the pulse ends.
        rst = 1'b1;
        duty = 4'd2;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        k = 0;
        while (pwm !== 1'b1 && k < 20) begin
            @(negedge clk);
            k = k + 1;
        end
        k = 0;
        while (pwm !== 1'b0 && k < 20) begin
            @(negedge clk);
            k = k + 1;
        end
        if (pwm !== 1'b0) begin
            failed = failed + 1;
            $display("CHECK duty_update.setup1 FAILED: no complete pulse seen with duty 2");
        end
        duty = 4'd7;
        lows = 0;
        repeat (4) begin
            @(negedge clk);
            if (pwm === 1'b0) lows = lows + 1;
        end
        if (lows == 4) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK duty_update.no_midperiod_rise FAILED: pwm rose within the period after duty changed 2->7 (low for %0d of 4 cycles)", lows);
        end
        k = 0;
        while (pwm !== 1'b1 && k < 12) begin
            @(negedge clk);
            k = k + 1;
        end
        if (pwm === 1'b1) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK duty_update.next_period_applies FAILED: new duty never took effect");
        end

        // Scenario 2: drop duty during the pulse.
        rst = 1'b1;
        duty = 4'd6;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        k = 0;
        while (pwm !== 1'b1 && k < 20) begin
            @(negedge clk);
            k = k + 1;
        end
        if (pwm !== 1'b1) begin
            failed = failed + 1;
            $display("CHECK duty_update.setup2 FAILED: no pulse seen with duty 6");
        end
        duty = 4'd1;
        w = 1;
        done = 1'b0;
        while (!done && w < 20) begin
            @(negedge clk);
            if (pwm === 1'b1) w = w + 1;
            else done = 1'b1;
        end
        if (w >= 6 && w < 20) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK duty_update.no_midperiod_fall FAILED: pulse lasted %0d cycles after duty changed 6->1 mid-pulse, expected at least 6", w);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===

